import json, re
from pathlib import Path

def load(p):
    return [json.loads(l) for l in Path(p).read_text().splitlines() if l.strip()]

def norm(g):
    return str(g).replace(",", "").replace("$","").strip()

def strict_full(s):
    sols = re.findall(r"#### (\-?[0-9\.\,]+)", s)
    return sols[-1].replace(",", "").replace("$", "") if sols else None

def last_num_tail(s, n=500):
    ans = re.findall(r"(\-?[0-9\.\,]+)", s[-n:])
    for a in reversed(ans):
        if a not in ("", "."):
            return a.replace(",", "")
    return None

# repetition: fraction of output that is duplicated lines
def dup_line_frac(o):
    lines = [ln.strip() for ln in o.splitlines() if ln.strip()]
    if not lines: return 0
    return 1 - len(set(lines))/len(lines)

for label, p in [("r1","results/run100/rollouts/1.jsonl"),("r50","results/run100/rollouts/50.jsonl"),("r100","results/run100/rollouts/100.jsonl"),
                 ("v0","results/run100/val_generations/0.jsonl"),("v100","results/run100/val_generations/100.jsonl")]:
    rows = load(p)
    fracs = [dup_line_frac(r["output"]) for r in rows]
    # consecutive repeated #### answer lines
    rep_tail = 0
    for r in rows:
        if re.search(r"(####[^\n]*\n)\1", r["output"]):
            rep_tail += 1
    # gibberish: very low unique word ratio
    uniq = []
    for r in rows:
        w = r["output"].split()
        uniq.append(len(set(w))/len(w) if w else 0)
    print(f"{label} dup_line mean {sum(fracs)/len(fracs):.3f} p90 {sorted(fracs)[int(0.9*len(fracs))]:.3f} repeated_hash_block {rep_tail} uniq_word mean {sum(uniq)/len(uniq):.3f}")

# val0 vs val100: reasoning change on problems that were flex-correct
rows0 = {r["input"]: r for r in load("results/run100/val_generations/0.jsonl")}
rows100 = {r["input"]: r for r in load("results/run100/val_generations/100.jsonl")}

# count categories more carefully using FULL string strict and last number anywhere
cat = {"fmt_only_fix":0, "both_wrong":0, "both_right_fmt":0, "gained_answer":0, "lost_answer":0, "fmt_and_still_wrong_num":0}
# flex anywhere in full string
def any_num_eq(s, gt):
    ans = re.findall(r"(\-?[0-9\.\,]+)", s)
    nums=set()
    for a in ans:
        if a not in ("","."):
            nums.add(a.replace(",",""))
    return gt in nums

examples = {"gained_answer":[], "lost_answer":[], "fmt_only_fix":[], "fmt_and_still_wrong_num":[]}
for inp, r0 in rows0.items():
    r1 = rows100[inp]
    gt = norm(r0["gts"])
    s0 = strict_full(r0["output"])==gt
    s1 = strict_full(r1["output"])==gt
    # flexible: last number in full text
    f0 = last_num_tail(r0["output"], 10**9)==gt
    f1 = last_num_tail(r1["output"], 10**9)==gt
    if s0 and s1:
        cat["both_right_fmt"] += 1
    elif (not s0) and s1 and f0:
        cat["fmt_only_fix"] += 1
        if len(examples["fmt_only_fix"])<1:
            examples["fmt_only_fix"].append((gt, r0["output"][-180:], r1["output"][-180:]))
    elif (not s0) and s1 and not f0:
        cat["gained_answer"] += 1
        if len(examples["gained_answer"])<2:
            examples["gained_answer"].append((gt, r0["output"][-300:], r1["output"][-300:]))
    elif s0 and not s1:
        cat["lost_answer"] += 1
    elif f0 and not s1:
        cat["fmt_and_still_wrong_num"] += 1  # had answer as last number, now strict wrong
        if len(examples["fmt_and_still_wrong_num"])<1:
            examples["fmt_and_still_wrong_num"].append((gt, strict_full(r1["output"]), r1["output"][-200:]))
    else:
        cat["both_wrong"] += 1
print("CAT", cat, "sum", sum(cat.values()), "n", len(rows0))

# Among val100 strict-correct, how often is the number also the only number vs reasoning contains intermediate
# Check train/val score gap stability late
# group variance at step 100: fraction of prompts with zero reward variance (all same score) -> no learning signal
from collections import defaultdict
for label,p in [("r1","results/run100/rollouts/1.jsonl"),("r50","results/run100/rollouts/50.jsonl"),("r100","results/run100/rollouts/100.jsonl")]:
    rows=load(p)
    g=defaultdict(list)
    for r in rows:
        g[r["input"]].append(r["score"])
    zero_var=0
    pos_var=0
    for scores in g.values():
        if max(scores)-min(scores)==0:
            zero_var += 1
        else:
            pos_var += 1
    print(label, "zero_var_groups", zero_var, "pos_var", pos_var, "of", len(g))

# response length tokens approx via words vs clip 512. Check how many outputs look cut off at val100 (no ending punctuation and long)
rows=load("results/run100/val_generations/100.jsonl")
cut=0
for r in rows:
    o=r["output"].rstrip()
    if len(o)>1800 and not re.search(r"#### \-?[0-9\.,]+\s*$", o):
        cut += 1
print("val100 long and no terminal #### num", cut)

# Does logged acc equal strict? already yes.
# Check if train reward > val because of sampling temp 1 vs greedy: compare pass@group vs mean
print("--- examples gained ---")
for e in examples["gained_answer"]:
    print("GT", e[0])
    print("OLD", e[1].replace("\n"," | ")[:300])
    print("NEW", e[2].replace("\n"," | ")[:300])
    print("---")
print("--- fmt only ---")
for e in examples["fmt_only_fix"]:
    print("GT", e[0])
    print("OLD", e[1].replace("\n"," | ")[:250])
    print("NEW", e[2].replace("\n"," | ")[:250])
